mapper.select:
/* saleson.shop.offgive.OffgiveMapper.getOffgiveList */ SELECT T.CNTR_SN, T.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE, ( SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = T.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y' ) AS UPPER_LOCGOV_NM, T.LOCGOV_CODE AS LOCGOV_CODE, T.LOCGOV_NM AS LOCGOV_NM, T.STTEMNT_PAY_DE, -- 수납일 T.USER_NAME as USER_NAME, -- 이름 T.CNTR_AMT, -- 기부금액 T.ELCTRN_PAY_NO, -- 전자납부번호 T.RCEPT_BANK_CODE, -- 접수은행코드 ( SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = T.RCEPT_BANK_CODE AND CODE_TYPE = 'OFF_BANK_LIST' AND USE_YN = 'Y' ) AS RCEPT_BANK_CODE_NM, T.RCEPT_BANK_NM, -- 접수지점 T.FRST_REGIST_PNTTM, -- 신고일시 T.CNTR_STTUS_CODE, -- 상태 (신고/정상/취소) T.CNTR_PATH_CODE, T.CNTR_POINT, T.RTNPSNT_REQST_CODE, T.PRJ_ID, T.PRJ_SUBJECT FROM ( SELECT CNTR_SN, GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE, GL.LOCGOV_CODE AS LOCGOV_CODE, GL.LOCGOV_NM AS LOCGOV_NM, GC.STTEMNT_PAY_DE, OU.USER_NAME, GC.CNTR_AMT, GC.ELCTRN_PAY_NO, GC.RCEPT_BANK_CODE, CASE WHEN GC.CNTR_PATH_CODE = '300' THEN LPWC.PBADMS_WLFR_CNTR_NM ELSE GC.RCEPT_BANK_NM END AS RCEPT_BANK_NM, GC.FRST_REGIST_PNTTM, GC.CNTR_STTUS_CODE, GC.CNTR_PATH_CODE, GC.CNTR_POINT, GC.RTNPSNT_REQST_CODE, NVL(GC.DSGN_DNTN_BIZ_ID, 0) AS PRJ_ID, NVL(DPM.DSGN_DNTN_BIZ_TTL, '자치단체에 기부하기') AS PRJ_SUBJECT FROM G_CNTR GC LEFT JOIN G_DSGN_DNTN_BIZ_MNG DPM ON GC.DSGN_DNTN_BIZ_ID = DPM.DSGN_DNTN_BIZ_ID LEFT JOIN G_LCLGV_PBADMS_WLFR_CNTR_MNG LPWC ON GC.RCEPT_BANK_CODE = LPWC.PBADMS_WLFR_CNTR_ID , G_LOCGOV GL, OP_USER OU WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.USER_ID = OU.USER_ID AND GC.CNTR_PATH_CODE IN ('200', '300') AND GC.DELETE_AT = 'N'
AND GC.CNTR_SN = #{shText} -- 접수번호
AND CONCAT(UPPER_LOCGOV_NM, ' ', LOCGOV_NM) LIKE CONCAT('%', #{shText}, '%') -- 기부 지자체
AND GC.ELCTRN_PAY_NO = #{shText} -- 전자납부번호
AND (GC.RCEPT_BANK_NM LIKE CONCAT('%', #{shText}, '%') OR LPWC.PBADMS_WLFR_CNTR_NM LIKE CONCAT('%', #{shText}, '%') )
AND DATE_FORMAT(GC.FRST_REGIST_PNTTM,'%Y%m%d') BETWEEN #{shFrstRegistPnttmStart} AND #{shFrstRegistPnttmEnd}
AND GC.CNTR_AMT BETWEEN #{shCntrAmtStart} AND #{shCntrAmtEnd}
AND GC.CNTR_STTUS_CODE = #{shCntrSttusCode}
AND GC.RCEPT_BANK_CODE = #{shRceptBankCode}
AND GC.CNTR_PATH_CODE = '200'
AND GC.CNTR_PATH_CODE = '300'
AND GC.RCEPT_BANK_NM = #{shRceptBankNm}
ORDER BY GC.FRST_REGIST_PNTTM DESC ) T

/* saleson.shop.offgive.OffgiveMapper.getManager */
select
	*
from OP_MANAGER
where status_code = 9
and user_id = #{userId}

/* saleson.shop.offgive.OffgiveMapper.getGMberSecsnSumCntrAmt */
select IFNULL(sum(cntr_amt), 0) as MAX_CNTR_AMT
from G_MBER_SECSN
where mber_ci = #{mberCi}
and secsn_year = DATE_FORMAT(NOW(), '%Y')

/* saleson.shop.offgive.SlaveOffgiveMapper.selectWlfrCntrMngList */ SELECT A.PBADMS_WLFR_CNTR_ID , B.UPPER_LOCGOV_CODE , A.LCLGV_CD , B.UPPER_LOCGOV_NM , B.LOCGOV_NM , A.PBADMS_WLFR_CNTR_NM , A.USE_YN , A.FRST_REG_DT FROM G_LCLGV_PBADMS_WLFR_CNTR_MNG A LEFT OUTER JOIN G_LOCGOV B ON A.LCLGV_CD = B.LOCGOV_CODE WHERE 1=1
AND LCLGV_CD = #{lclgvCd}
AND LCLGV_CD IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
AND pbadms_wlfr_cntr_nm LIKE CONCAT('%', #{pbadmsWlfrCntrNm}, '%')
AND use_yn = #{useYn}
AND frst_reg_dt >= CONCAT(#{searchStDt}, '000000')
AND frst_reg_dt <= CONCAT(#{searchEdDt}, '235959')
ORDER BY PBADMS_WLFR_CNTR_ID DESC

SELECT count(*) FROM ( SELECT A.PBADMS_WLFR_CNTR_ID , B.UPPER_LOCGOV_CODE , A.LCLGV_CD , B.UPPER_LOCGOV_NM , B.LOCGOV_NM , A.PBADMS_WLFR_CNTR_NM , A.USE_YN , A.FRST_REG_DT FROM G_LCLGV_PBADMS_WLFR_CNTR_MNG A LEFT OUTER JOIN G_LOCGOV B ON A.LCLGV_CD = B.LOCGOV_CODE WHERE 1=1
AND LCLGV_CD = #{lclgvCd}
AND LCLGV_CD IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
AND pbadms_wlfr_cntr_nm LIKE CONCAT('%', #{pbadmsWlfrCntrNm}, '%')
AND use_yn = #{useYn}
AND frst_reg_dt >= CONCAT(#{searchStDt}, '000000')
AND frst_reg_dt <= CONCAT(#{searchEdDt}, '235959')
)

