	, USE_YN
	, FRST_REG_DT
)
VALUES(
	#{lclgvCd}
	, #{pbadmsWlfrCntrNm}
	, #{pbadmsWlfrCntrCd}
	, #{useYn}
	, CURRENT_TIMESTAMP
)

