	PBADMS_WLFR_CNTR_NM = #{pbadmsWlfrCntrNm}
	, PBADMS_WLFR_CNTR_CD = #{pbadmsWlfrCntrCd}
	, USE_YN = #{useYn}
WHERE 1=1
AND	PBADMS_WLFR_CNTR_ID = #{pbadmsWlfrCntrId}

